insert into public.learning_content
(content_id, faculty, subject, content_type, access_tier, display_order, content_data, is_published)
values
('dph-chemistry-extra-mcq-01','Pharmacy','Diploma in Pharmacy','mcq','free',1801,'{"question":"Pharmaceutical chemistry mainly deals with:","translation":"Pharmaceutical chemistry मुख्यतः केसँग सम्बन्धित छ?","options":["Chemical properties and analysis of substances used as medicines","Hospital building design","Patient appointment scheduling","Dental impression techniques"],"correctIndex":0,"explanation":"It applies chemistry to the identity, properties, quality and analysis of pharmaceutical substances.","explanationNe":"यसले औषधीय पदार्थको पहिचान, गुण, गुणस्तर र विश्लेषणमा रसायनशास्त्र प्रयोग गर्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-02','Pharmacy','Diploma in Pharmacy','mcq','free',1802,'{"question":"An atom is best described as:","translation":"Atom लाई कसरी वर्णन गरिन्छ?","options":["Smallest unit of an element retaining its chemical identity","A mixture of two compounds","A visible crystal only","A type of solution"],"correctIndex":0,"explanation":"An atom is the basic unit of an element that retains its chemical properties.","explanationNe":"Atom तत्वको आधारभूत एकाइ हो जसले त्यसका रासायनिक गुण कायम राख्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-03','Pharmacy','Diploma in Pharmacy','mcq','free',1803,'{"question":"The atomic number of an element equals the number of:","translation":"तत्वको atomic number के बराबर हुन्छ?","options":["Protons","Neutrons","Protons plus neutrons","Electron shells"],"correctIndex":0,"explanation":"Atomic number is the number of protons in the nucleus.","explanationNe":"Atomic number भनेको nucleus मा रहेका proton को संख्या हो।"}'::jsonb,true),
('dph-chemistry-extra-mcq-04','Pharmacy','Diploma in Pharmacy','mcq','free',1804,'{"question":"A chemical bond formed by sharing electron pairs is:","translation":"Electron pair साझा गरेर बन्ने bond कुन हो?","options":["Covalent bond","Ionic bond","Metallic bond only","Hydrogen bond only"],"correctIndex":0,"explanation":"Covalent bonding involves sharing electron pairs between atoms.","explanationNe":"Covalent bond मा atom हरूबीच electron pair साझा हुन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-05','Pharmacy','Diploma in Pharmacy','mcq','free',1805,'{"question":"An ionic bond is primarily formed by:","translation":"Ionic bond मुख्यतः कसरी बन्छ?","options":["Electrostatic attraction between oppositely charged ions","Sharing a pair of electrons equally","Mixing two liquids","Breaking all nuclei"],"correctIndex":0,"explanation":"Ionic bonding involves attraction between cations and anions, commonly after electron transfer.","explanationNe":"Ionic bond मा धनायन र ऋणायनबीच आकर्षण हुन्छ, प्रायः electron स्थानान्तरणपछि।"}'::jsonb,true),
('dph-chemistry-extra-mcq-06','Pharmacy','Diploma in Pharmacy','mcq','free',1806,'{"question":"A molecule containing two atoms is called:","translation":"दुई atom भएको molecule लाई के भनिन्छ?","options":["Diatomic molecule","Polyatomic molecule","Isotope","Polymer"],"correctIndex":0,"explanation":"A diatomic molecule consists of two atoms, which may be identical or different.","explanationNe":"Diatomic molecule दुई atom बाट बनेको हुन्छ, ती समान वा फरक हुन सक्छन्।"}'::jsonb,true),
('dph-chemistry-extra-mcq-07','Pharmacy','Diploma in Pharmacy','mcq','free',1807,'{"question":"The pH of an acidic aqueous solution at about 25°C is generally:","translation":"करिब २५°C मा अम्लीय जलीय solution को pH सामान्यतया कस्तो हुन्छ?","options":["Less than 7","Exactly 7","Greater than 7","Always 14"],"correctIndex":0,"explanation":"At about 25°C, an acidic aqueous solution has pH below 7.","explanationNe":"करिब २५°C मा अम्लीय जलीय solution को pH ७ भन्दा कम हुन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-08','Pharmacy','Diploma in Pharmacy','mcq','free',1808,'{"question":"A strong acid in water:","translation":"पानीमा strong acid ले के गर्छ?","options":["Ionizes extensively","Does not ionize at all","Always forms a precipitate","Has pH exactly 7"],"correctIndex":0,"explanation":"Strong acids ionize extensively in aqueous solution; strength is not the same as concentration.","explanationNe":"Strong acid पानीमा धेरै हदसम्म ionize हुन्छ; strength र concentration एउटै कुरा होइनन्।"}'::jsonb,true),
('dph-chemistry-extra-mcq-09','Pharmacy','Diploma in Pharmacy','mcq','free',1809,'{"question":"A base is a substance that can:","translation":"Base भनेको के गर्न सक्ने पदार्थ हो?","options":["Accept a proton or produce hydroxide ions in water, depending on the definition","Donate only neutrons","Always have pH below 7","Prevent all reactions"],"correctIndex":0,"explanation":"Common acid-base definitions include proton acceptance or hydroxide production in aqueous solution.","explanationNe":"सामान्य परिभाषाअनुसार base ले proton ग्रहण गर्न वा पानीमा hydroxide ion दिन सक्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-10','Pharmacy','Diploma in Pharmacy','mcq','free',1810,'{"question":"A buffer solution resists changes in:","translation":"Buffer solution ले कुन परिवर्तनलाई प्रतिरोध गर्छ?","options":["pH","Mass","Colour of every substance","Volume in all circumstances"],"correctIndex":0,"explanation":"A buffer limits pH change when small quantities of acid or base are added.","explanationNe":"थोरै acid वा base थप्दा buffer ले pH परिवर्तन सीमित गर्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-11','Pharmacy','Diploma in Pharmacy','mcq','free',1811,'{"question":"The conjugate base of hydrochloric acid (HCl) is:","translation":"Hydrochloric acid (HCl) को conjugate base कुन हो?","options":["Chloride ion","Sodium ion","Hydroxide ion","Ammonium ion"],"correctIndex":0,"explanation":"After donating a proton, HCl forms chloride ion, Cl−.","explanationNe":"HCl ले proton दिएपछि chloride ion (Cl−) बन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-12','Pharmacy','Diploma in Pharmacy','mcq','free',1812,'{"question":"Oxidation is commonly defined as:","translation":"Oxidation को सामान्य परिभाषा के हो?","options":["Loss of electrons","Gain of electrons","Gain of neutrons","Loss of protons only"],"correctIndex":0,"explanation":"Oxidation involves loss of electrons and an increase in oxidation state.","explanationNe":"Oxidation मा electron गुम्छ र oxidation state बढ्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-13','Pharmacy','Diploma in Pharmacy','mcq','free',1813,'{"question":"Reduction is commonly defined as:","translation":"Reduction को सामान्य परिभाषा के हो?","options":["Gain of electrons","Loss of electrons","Gain of oxygen only in every case","Loss of neutrons"],"correctIndex":0,"explanation":"Reduction involves gain of electrons and a decrease in oxidation state.","explanationNe":"Reduction मा electron प्राप्त हुन्छ र oxidation state घट्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-14','Pharmacy','Diploma in Pharmacy','mcq','free',1814,'{"question":"A substance that donates electrons in a redox reaction is the:","translation":"Redox reaction मा electron दिने पदार्थ कुन हो?","options":["Reducing agent","Oxidizing agent","Indicator","Buffer"],"correctIndex":0,"explanation":"The reducing agent donates electrons and is itself oxidized.","explanationNe":"Reducing agent ले electron दिन्छ र आफैँ oxidized हुन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-15','Pharmacy','Diploma in Pharmacy','mcq','free',1815,'{"question":"A standard solution is one whose:","translation":"Standard solution भन्नाले कस्तो solution बुझिन्छ?","options":["Concentration is accurately known","Colour is always blue","Volume is always one litre","Solute is always a gas"],"correctIndex":0,"explanation":"A standard solution has a reliably known concentration for quantitative analysis.","explanationNe":"Standard solution को concentration विश्वसनीय रूपमा थाहा हुन्छ र quantitative analysis मा प्रयोग हुन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-16','Pharmacy','Diploma in Pharmacy','mcq','free',1816,'{"question":"Titration is a method used to determine:","translation":"Titration कुन कुरा निर्धारण गर्न प्रयोग हुन्छ?","options":["Unknown concentration using a solution of known concentration","Only melting point","Only tablet colour","The age of a patient"],"correctIndex":0,"explanation":"In titration, a measured amount of standard solution reacts with the analyte to determine its concentration.","explanationNe":"Titration मा ज्ञात concentration भएको solution प्रयोग गरी नमुनाको concentration पत्ता लगाइन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-17','Pharmacy','Diploma in Pharmacy','mcq','free',1817,'{"question":"The endpoint of an indicator titration is commonly shown by:","translation":"Indicator titration को endpoint सामान्यतया कसरी देखिन्छ?","options":["A colour change","A change in room temperature only","A sound","A change in container size"],"correctIndex":0,"explanation":"An indicator changes colour over a particular pH range near the endpoint.","explanationNe":"Endpoint नजिक indicator ले निश्चित pH दायरामा रङ परिवर्तन गर्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-18','Pharmacy','Diploma in Pharmacy','mcq','free',1818,'{"question":"A primary standard substance should ideally be:","translation":"Primary standard पदार्थमा कुन गुण हुनुपर्छ?","options":["High purity and stability","Highly volatile and impure","Strongly hygroscopic","Of unknown composition"],"correctIndex":0,"explanation":"A primary standard should be sufficiently pure, stable and suitable for accurate weighing.","explanationNe":"Primary standard पर्याप्त शुद्ध, स्थिर र सही तौल गर्न उपयुक्त हुनुपर्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-19','Pharmacy','Diploma in Pharmacy','mcq','free',1819,'{"question":"Molarity is expressed as:","translation":"Molarity कसरी व्यक्त गरिन्छ?","options":["Moles of solute per litre of solution","Grams per 100 g of solvent","Millilitres per kilogram","Moles per gram of solute"],"correctIndex":0,"explanation":"Molarity is the number of moles of solute in one litre of final solution.","explanationNe":"Molarity भनेको एक litre अन्तिम solution मा भएको solute को mole संख्या हो।"}'::jsonb,true),
('dph-chemistry-extra-mcq-20','Pharmacy','Diploma in Pharmacy','mcq','free',1820,'{"question":"The molar mass of a compound is the:","translation":"Compound को molar mass के हो?","options":["Mass of one mole of the substance","Mass of one atom only","Volume of one litre","Number of electrons"],"correctIndex":0,"explanation":"Molar mass is expressed as mass per mole, commonly g/mol.","explanationNe":"Molar mass भनेको प्रति mole पदार्थको mass हो, सामान्यतया g/mol मा।"}'::jsonb,true),
('dph-chemistry-extra-mcq-21','Pharmacy','Diploma in Pharmacy','mcq','free',1821,'{"question":"A 0.5 M solution contains:","translation":"0.5 M solution मा के हुन्छ?","options":["0.5 mole solute per litre of solution","0.5 gram per litre in every case","5 moles per 100 mL","50 moles per litre"],"correctIndex":0,"explanation":"Molarity expresses moles of solute per litre of final solution.","explanationNe":"Molarity ले अन्तिम solution को प्रति litre solute का mole जनाउँछ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-22','Pharmacy','Diploma in Pharmacy','mcq','free',1822,'{"question":"The formula for calculating moles is:","translation":"Mole गणना गर्ने सूत्र कुन हो?","options":["Mass divided by molar mass","Molar mass divided by volume","Volume multiplied by density only","pH multiplied by mass"],"correctIndex":0,"explanation":"Number of moles equals mass in grams divided by molar mass in g/mol.","explanationNe":"Mole संख्या = ग्राममा mass ÷ g/mol मा molar mass।"}'::jsonb,true),
('dph-chemistry-extra-mcq-23','Pharmacy','Diploma in Pharmacy','mcq','free',1823,'{"question":"A precipitate is:","translation":"Precipitate भनेको के हो?","options":["An insoluble solid formed in a solution reaction","A gas dissolved in water","A pure solvent","A colourless indicator"],"correctIndex":0,"explanation":"A precipitate is a solid that separates from solution during a chemical reaction.","explanationNe":"रासायनिक प्रतिक्रियामा solution बाट छुट्टिएर निस्कने अघुलनशील ठोसलाई precipitate भनिन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-24','Pharmacy','Diploma in Pharmacy','mcq','free',1824,'{"question":"A qualitative chemical test is used to identify:","translation":"Qualitative chemical test के पहिचान गर्न प्रयोग हुन्छ?","options":["Presence or identity of a substance or ion","Exact quantity only","Patient weight","Storage temperature only"],"correctIndex":0,"explanation":"Qualitative analysis indicates whether a particular substance or ion is present.","explanationNe":"Qualitative analysis ले कुनै पदार्थ वा ion उपस्थित छ कि छैन भन्ने देखाउँछ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-25','Pharmacy','Diploma in Pharmacy','mcq','free',1825,'{"question":"Quantitative analysis determines:","translation":"Quantitative analysis ले के निर्धारण गर्छ?","options":["Amount or concentration of a substance","Only its colour","Only its smell","Only its packaging"],"correctIndex":0,"explanation":"Quantitative analysis measures how much of a substance is present.","explanationNe":"Quantitative analysis ले पदार्थको मात्रा वा concentration मापन गर्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-26','Pharmacy','Diploma in Pharmacy','mcq','free',1826,'{"question":"A reagent is:","translation":"Reagent भनेको के हो?","options":["A substance used to cause or detect a chemical reaction","A finished medicine label","A storage shelf","A measuring balance"],"correctIndex":0,"explanation":"Reagents are chemicals used in analysis or chemical reactions.","explanationNe":"Reagent भनेको विश्लेषण वा रासायनिक प्रतिक्रियामा प्रयोग हुने रसायन हो।"}'::jsonb,true),
('dph-chemistry-extra-mcq-27','Pharmacy','Diploma in Pharmacy','mcq','free',1827,'{"question":"Distilled water is commonly used in laboratory work because it:","translation":"Laboratory मा distilled water किन प्रयोग गरिन्छ?","options":["Contains fewer dissolved impurities than ordinary water","Always contains medicine","Is always sterile","Has a fixed pH of 7 under all conditions"],"correctIndex":0,"explanation":"Distillation reduces many dissolved impurities; suitability depends on the test or preparation.","explanationNe":"Distillation ले धेरै घुलिएका अशुद्धता घटाउँछ; उपयुक्तता परीक्षण वा तयारीमा निर्भर हुन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-28','Pharmacy','Diploma in Pharmacy','mcq','free',1828,'{"question":"An electrolyte in solution:","translation":"Solution मा electrolyte ले के गर्छ?","options":["Produces mobile ions and conducts electricity","Always remains as neutral molecules only","Cannot dissolve in water","Is necessarily a strong acid"],"correctIndex":0,"explanation":"Electrolytes form ions in solution or molten state, enabling electrical conduction.","explanationNe":"Electrolyte ले solution वा पग्लिएको अवस्थामा ion बनाउँछ र विद्युत् प्रवाह सम्भव बनाउँछ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-29','Pharmacy','Diploma in Pharmacy','mcq','free',1829,'{"question":"Sodium chloride in water mainly dissociates into:","translation":"पानीमा sodium chloride मुख्यतः केमा छुट्टिन्छ?","options":["Sodium and chloride ions","Hydrogen and oxygen","Calcium and carbonate ions","Ammonium and nitrate ions"],"correctIndex":0,"explanation":"NaCl dissociates into Na+ and Cl− ions in water.","explanationNe":"NaCl पानीमा Na+ र Cl− ion मा छुट्टिन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-30','Pharmacy','Diploma in Pharmacy','mcq','free',1830,'{"question":"The chemical formula of sodium bicarbonate is:","translation":"Sodium bicarbonate को chemical formula कुन हो?","options":["NaHCO3","NaCl","CaCO3","KCl"],"correctIndex":0,"explanation":"Sodium bicarbonate is NaHCO3.","explanationNe":"Sodium bicarbonate को सूत्र NaHCO3 हो।"}'::jsonb,true),
('dph-chemistry-extra-mcq-31','Pharmacy','Diploma in Pharmacy','mcq','free',1831,'{"question":"The chemical formula of calcium carbonate is:","translation":"Calcium carbonate को chemical formula कुन हो?","options":["CaCO3","CaCl2","Na2CO3","MgSO4"],"correctIndex":0,"explanation":"Calcium carbonate is CaCO3.","explanationNe":"Calcium carbonate को सूत्र CaCO3 हो।"}'::jsonb,true),
('dph-chemistry-extra-mcq-32','Pharmacy','Diploma in Pharmacy','mcq','free',1832,'{"question":"Activated charcoal is used in some poisoning cases because it can:","translation":"केही विषाक्ततामा activated charcoal किन प्रयोग गरिन्छ?","options":["Adsorb certain substances in the gastrointestinal tract","Neutralize every poison","Act as a universal antidote","Replace emergency assessment"],"correctIndex":0,"explanation":"Activated charcoal adsorbs certain substances; it is not effective for all poisons and requires appropriate clinical assessment.","explanationNe":"Activated charcoal ले केही पदार्थलाई सतहमा adsorb गर्छ; सबै विषमा प्रभावकारी हुँदैन र चिकित्सकीय मूल्याङ्कन आवश्यक हुन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-33','Pharmacy','Diploma in Pharmacy','mcq','free',1833,'{"question":"An antacid generally works by:","translation":"Antacid ले सामान्यतया कसरी काम गर्छ?","options":["Neutralizing gastric acid","Increasing gastric acidity","Destroying all bacteria","Inhibiting all enzymes"],"correctIndex":0,"explanation":"Antacids neutralize some gastric acid and provide symptomatic relief.","explanationNe":"Antacid ले पेटको केही acid neutralize गरी लक्षणमा राहत दिन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-34','Pharmacy','Diploma in Pharmacy','mcq','free',1834,'{"question":"A hygroscopic substance tends to:","translation":"Hygroscopic पदार्थको विशेषता के हो?","options":["Absorb moisture from the air","Repel all water","Evaporate instantly","Become radioactive"],"correctIndex":0,"explanation":"Hygroscopic materials absorb moisture from their surroundings and may need protective storage.","explanationNe":"Hygroscopic पदार्थले वरिपरिको हावाबाट चिस्यान सोस्छ र सुरक्षित भण्डारण आवश्यक पर्न सक्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-35','Pharmacy','Diploma in Pharmacy','mcq','free',1835,'{"question":"A deliquescent substance:","translation":"Deliquescent पदार्थले के गर्छ?","options":["Absorbs moisture until it may dissolve in the absorbed water","Loses all water instantly","Cannot absorb moisture","Always forms a gas"],"correctIndex":0,"explanation":"Deliquescent substances absorb enough atmospheric moisture to form a solution.","explanationNe":"Deliquescent पदार्थले हावाबाट यति धेरै चिस्यान सोस्छ कि आफैँ solution बन्न सक्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-36','Pharmacy','Diploma in Pharmacy','mcq','free',1836,'{"question":"A volatile substance is one that:","translation":"Volatile पदार्थ कस्तो हुन्छ?","options":["Evaporates readily","Never changes to vapour","Always absorbs water","Cannot be weighed"],"correctIndex":0,"explanation":"Volatile substances pass into vapour relatively readily under given conditions.","explanationNe":"Volatile पदार्थ निश्चित अवस्थामा तुलनात्मक रूपमा सजिलै वाष्पमा परिणत हुन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-37','Pharmacy','Diploma in Pharmacy','mcq','free',1837,'{"question":"The purpose of an assay is to determine:","translation":"Assay को उद्देश्य के हो?","options":["The content or potency of an active ingredient","Only the package size","Only the product colour","The patient''s diagnosis"],"correctIndex":0,"explanation":"An assay quantitatively determines the amount or strength of an active substance in a sample.","explanationNe":"Assay ले नमुनामा सक्रिय पदार्थको मात्रा वा शक्ति quantitative रूपमा निर्धारण गर्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-38','Pharmacy','Diploma in Pharmacy','mcq','free',1838,'{"question":"A limit test is designed to check whether:","translation":"Limit test ले के जाँच गर्छ?","options":["A specified impurity is below a prescribed limit","The medicine has no active ingredient","The package is attractive","The patient has an allergy"],"correctIndex":0,"explanation":"Limit tests assess whether particular impurities do not exceed specified limits.","explanationNe":"Limit test ले निश्चित अशुद्धता तोकिएको सीमाभन्दा बढी छ कि छैन जाँच गर्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-39','Pharmacy','Diploma in Pharmacy','mcq','free',1839,'{"question":"The oxidation state of oxygen in most common compounds is:","translation":"धेरै सामान्य compound मा oxygen को oxidation state कति हुन्छ?","options":["−2","+2","0","+4"],"correctIndex":0,"explanation":"Oxygen is usually assigned an oxidation state of −2, with known exceptions.","explanationNe":"विशेष अपवादबाहेक oxygen को oxidation state सामान्यतया −2 हुन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mcq-40','Pharmacy','Diploma in Pharmacy','mcq','free',1840,'{"question":"A chemical formula represents:","translation":"Chemical formula ले के देखाउँछ?","options":["The elements and relative numbers of atoms in a substance","The retail price","The colour of a solution","The expiry date"],"correctIndex":0,"explanation":"A formula shows which elements are present and their atomic ratios.","explanationNe":"Formula ले कुन तत्व छन् र तिनको atom अनुपात कति छ भन्ने देखाउँछ।"}'::jsonb,true),
('dph-chemistry-extra-mock-01','Pharmacy','Diploma in Pharmacy','mock','free',1901,'{"question":"Define pharmaceutical chemistry and describe its relevance to pharmacy.","answer":"Pharmaceutical chemistry applies chemical principles to the identity, structure, properties, synthesis, analysis and quality of substances used in medicines.","answerNe":"Pharmaceutical chemistry ले औषधिमा प्रयोग हुने पदार्थको पहिचान, संरचना, गुण, synthesis, विश्लेषण र गुणस्तरमा रसायनशास्त्र लागू गर्छ।"}'::jsonb,true),
('dph-chemistry-extra-mock-02','Pharmacy','Diploma in Pharmacy','mock','free',1902,'{"question":"Differentiate qualitative and quantitative analysis with examples.","answer":"Qualitative analysis identifies the presence or identity of a substance or ion. Quantitative analysis determines its amount or concentration, for example by titration or assay.","answerNe":"Qualitative analysis ले पदार्थ वा ion उपस्थित छ कि छैन पहिचान गर्छ। Quantitative analysis ले titration वा assay जस्ता विधिबाट मात्रा वा concentration निर्धारण गर्छ।"}'::jsonb,true),
('dph-chemistry-extra-mock-03','Pharmacy','Diploma in Pharmacy','mock','free',1903,'{"question":"Define acid, base and pH.","answer":"An acid donates a proton under the Brønsted-Lowry definition; a base accepts a proton. pH expresses hydrogen-ion activity on a logarithmic scale; at about 25°C neutral aqueous solution is near pH 7.","answerNe":"Brønsted-Lowry अनुसार acid ले proton दिन्छ र base ले proton ग्रहण गर्छ। pH ले hydrogen-ion activity logarithmic scale मा जनाउँछ; करिब २५°C मा neutral पानीको pH लगभग ७ हुन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mock-04','Pharmacy','Diploma in Pharmacy','mock','free',1904,'{"question":"What is a buffer solution? Give its pharmaceutical importance.","answer":"A buffer resists pH changes after small additions of acid or base. It may help maintain stability, solubility and performance of suitable pharmaceutical preparations.","answerNe":"Buffer ले थोरै acid वा base थप्दा pH परिवर्तन रोक्न मद्दत गर्छ। उपयुक्त औषधीय तयारीमा stability, solubility र performance कायम राख्न उपयोगी हुन सक्छ।"}'::jsonb,true),
('dph-chemistry-extra-mock-05','Pharmacy','Diploma in Pharmacy','mock','free',1905,'{"question":"Explain oxidation and reduction with their electron changes.","answer":"Oxidation is loss of electrons and reduction is gain of electrons. They occur together in a redox reaction; the oxidizing agent accepts electrons and the reducing agent donates them.","answerNe":"Oxidation मा electron गुम्छ र reduction मा electron प्राप्त हुन्छ। यी redox reaction मा सँगसँगै हुन्छन्; oxidizing agent ले electron लिन्छ र reducing agent ले दिन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mock-06','Pharmacy','Diploma in Pharmacy','mock','free',1906,'{"question":"Define molarity and show how it is calculated.","answer":"Molarity is moles of solute per litre of final solution. Moles = mass in grams divided by molar mass; molarity = moles divided by solution volume in litres.","answerNe":"Molarity भनेको अन्तिम solution को प्रति litre solute का mole हो। Mole = ग्राममा mass ÷ molar mass; molarity = mole ÷ litre मा solution volume।"}'::jsonb,true),
('dph-chemistry-extra-mock-07','Pharmacy','Diploma in Pharmacy','mock','free',1907,'{"question":"Explain the principle of acid-base titration.","answer":"A measured volume of a solution of known concentration reacts stoichiometrically with the analyte. The endpoint is detected using a suitable indicator or instrumental method.","answerNe":"ज्ञात concentration भएको solution को निश्चित आयतनले analyte सँग stoichiometric अनुपातमा प्रतिक्रिया गर्छ। उपयुक्त indicator वा उपकरणबाट endpoint पत्ता लगाइन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mock-08','Pharmacy','Diploma in Pharmacy','mock','free',1908,'{"question":"State the characteristics of a good primary standard.","answer":"It should have high purity, known composition, stability in air, low hygroscopicity, reasonably high molar mass and react quantitatively according to a known equation.","answerNe":"यो उच्च शुद्धता, निश्चित संरचना, हावामा स्थिर, कम hygroscopic, उपयुक्त उच्च molar mass र ज्ञात समीकरणअनुसार पूर्ण प्रतिक्रिया गर्ने हुनुपर्छ।"}'::jsonb,true),
('dph-chemistry-extra-mock-09','Pharmacy','Diploma in Pharmacy','mock','free',1909,'{"question":"Differentiate a primary standard and a secondary standard solution.","answer":"A primary standard solution is prepared directly using a suitable highly pure stable substance. A secondary standard solution has its concentration determined by standardization against a primary standard or another suitable standard.","answerNe":"Primary standard solution उपयुक्त शुद्ध र स्थिर पदार्थबाट सीधै तयार गरिन्छ। Secondary standard को concentration primary वा अन्य उपयुक्त standard विरुद्ध standardization गरेर निर्धारण गरिन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mock-10','Pharmacy','Diploma in Pharmacy','mock','free',1910,'{"question":"What is an assay? Why is it important in pharmaceutical quality control?","answer":"An assay quantitatively measures the active ingredient content or potency. It helps verify that a medicine meets its specified strength and quality limits.","answerNe":"Assay ले सक्रिय ingredient को मात्रा वा potency मापन गर्छ। औषधिले तोकिएको शक्ति र गुणस्तर सीमा पूरा गरेको छ कि छैन पुष्टि गर्न मद्दत गर्छ।"}'::jsonb,true),
('dph-chemistry-extra-mock-11','Pharmacy','Diploma in Pharmacy','mock','free',1911,'{"question":"What is a limit test? How does it differ from an assay?","answer":"A limit test checks whether a specified impurity is within an allowed limit. An assay measures the amount or potency of the active ingredient.","answerNe":"Limit test ले निश्चित अशुद्धता स्वीकृत सीमाभित्र छ कि छैन जाँच्छ। Assay ले सक्रिय ingredient को मात्रा वा शक्ति मापन गर्छ।"}'::jsonb,true),
('dph-chemistry-extra-mock-12','Pharmacy','Diploma in Pharmacy','mock','free',1912,'{"question":"Explain the importance of reagents and reagent labelling in a laboratory.","answer":"Reagents are chemicals used for analysis or reactions. Labels should identify the reagent and relevant concentration, preparation details, date, hazard information and storage requirements according to laboratory procedure.","answerNe":"Reagent विश्लेषण वा प्रतिक्रियामा प्रयोग हुने रसायन हो। प्रयोगशाला प्रक्रियाअनुसार label मा नाम, concentration, तयारी मिति/विवरण, जोखिम र भण्डारण निर्देशन राख्नुपर्छ।"}'::jsonb,true),
('dph-chemistry-extra-mock-13','Pharmacy','Diploma in Pharmacy','mock','free',1913,'{"question":"Describe safe handling practices for laboratory chemicals.","answer":"Read labels and safety information, use appropriate PPE, avoid mouth pipetting, work with ventilation where needed, segregate incompatible chemicals, label containers and follow spill and waste procedures.","answerNe":"Label र safety जानकारी पढ्ने, PPE लगाउने, मुखले pipette नगर्ने, आवश्यक ventilation प्रयोग गर्ने, नमिल्ने रसायन छुट्याउने, container label गर्ने र spill/waste प्रक्रिया पालना गर्ने।"}'::jsonb,true),
('dph-chemistry-extra-mock-14','Pharmacy','Diploma in Pharmacy','mock','free',1914,'{"question":"What is the difference between an electrolyte and a non-electrolyte?","answer":"An electrolyte forms mobile ions in solution or molten state and conducts electricity. A non-electrolyte does not form appreciable ions under the same conditions.","answerNe":"Electrolyte ले solution वा पग्लिएको अवस्थामा चलायमान ion बनाई विद्युत् प्रवाह गर्छ। Non-electrolyte ले त्यस्तो अवस्थामा उल्लेखनीय ion बनाउँदैन।"}'::jsonb,true),
('dph-chemistry-extra-mock-15','Pharmacy','Diploma in Pharmacy','mock','free',1915,'{"question":"Describe the chemical composition and pharmaceutical uses of sodium bicarbonate.","answer":"Sodium bicarbonate has formula NaHCO3. It is used in appropriate formulations as an antacid or alkalinizing agent; its use depends on clinical indication and safety.","answerNe":"Sodium bicarbonate को सूत्र NaHCO3 हो। उपयुक्त तयारीमा antacid वा alkalinizing agent का रूपमा प्रयोग हुन सक्छ; प्रयोग clinical indication र सुरक्षामा निर्भर हुन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mock-16','Pharmacy','Diploma in Pharmacy','mock','free',1916,'{"question":"Describe the principle and limitation of activated charcoal.","answer":"Activated charcoal adsorbs certain substances onto its large surface area in the gastrointestinal tract. It is not a universal antidote and is unsuitable for some substances; use requires appropriate toxicology guidance.","answerNe":"Activated charcoal ले पाचननलीमा केही पदार्थलाई आफ्नो ठूलो सतहमा adsorb गर्छ। यो सबै विषको antidote होइन र केही पदार्थमा उपयोगी हुँदैन; प्रयोगका लागि उपयुक्त toxicology निर्देशन चाहिन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mock-17','Pharmacy','Diploma in Pharmacy','mock','free',1917,'{"question":"Explain the terms hygroscopic, deliquescent and volatile.","answer":"Hygroscopic substances absorb moisture from air. Deliquescent substances absorb enough moisture to form a solution. Volatile substances evaporate readily under given conditions.","answerNe":"Hygroscopic पदार्थले हावाबाट चिस्यान सोस्छ। Deliquescent पदार्थले यति चिस्यान सोस्छ कि solution बन्न सक्छ। Volatile पदार्थ निश्चित अवस्थामा सजिलै वाष्प बन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mock-18','Pharmacy','Diploma in Pharmacy','mock','free',1918,'{"question":"What is a precipitate? Explain its relevance in qualitative analysis.","answer":"A precipitate is an insoluble solid formed during a reaction in solution. Its formation, colour and solubility behaviour can help identify certain ions or compounds using validated procedures.","answerNe":"Solution मा प्रतिक्रियाबाट बन्ने अघुलनशील ठोस precipitate हो। यसको निर्माण, रङ र घुलनशीलताले प्रमाणित विधिअनुसार केही ion वा compound पहिचान गर्न मद्दत गर्छ।"}'::jsonb,true),
('dph-chemistry-extra-mock-19','Pharmacy','Diploma in Pharmacy','mock','free',1919,'{"question":"Why is distilled or purified water used in pharmaceutical analysis?","answer":"It reduces interfering dissolved impurities that may affect reactions, measurements or product quality. The required grade depends on the analytical method or preparation.","answerNe":"यसले प्रतिक्रिया, मापन वा उत्पादन गुणस्तरमा असर गर्ने घुलिएका अशुद्धता घटाउँछ। आवश्यक water grade विश्लेषण विधि वा तयारीअनुसार हुन्छ।"}'::jsonb,true),
('dph-chemistry-extra-mock-20','Pharmacy','Diploma in Pharmacy','mock','free',1920,'{"question":"Explain the importance of chemical calculations in pharmacy.","answer":"Accurate calculations are needed for concentration, dilution, dose preparation, assay, compounding and quality control. Units and final volumes must be checked carefully to prevent errors.","answerNe":"Concentration, dilution, dose तयारी, assay, compounding र quality control मा सही गणना आवश्यक हुन्छ। त्रुटि रोक्न एकाइ र अन्तिम आयतन ध्यानपूर्वक जाँच्नुपर्छ।"}'::jsonb,true)
